import numpy as np
from scipy.optimize import least_squares
e=eps; t=T; y=sigma
def fit(model,n,k=60):
    rng=np.random.default_rng(1); best=None
    for _ in range(k):
        p0=rng.normal(size=n)
        try:
            r=least_squares(lambda p: model(p)-y, p0, max_nfev=3000)
            if np.all(np.isfinite(r.fun)) and (best is None or r.cost<best.cost): best=r
        except Exception: pass
    return best, np.mean((model(best.x)-y)**2)/np.var(y)
